<?php
declare(strict_types=1);
require_once __DIR__ . '/../functions/helpers.php';
require_role('customer');

$stmt = db()->prepare('SELECT u.name,u.email,p.phone,p.address_line1,p.address_line2,p.city,p.province,p.postal_code,p.country FROM users u LEFT JOIN profiles p ON p.user_id=u.id WHERE u.id=? LIMIT 1');
$stmt->execute([$_SESSION['user_id']]);
$profile = $stmt->fetch() ?: ['name'=>'','email'=>'','phone'=>'','address_line1'=>'','address_line2'=>'','city'=>'','province'=>'','postal_code'=>'','country'=>'Philippines'];
$errors = $_SESSION['profile_errors'] ?? [];
$old = $_SESSION['profile_old'] ?? $profile;
unset($_SESSION['profile_errors'], $_SESSION['profile_old']);
$flash = get_flash();
